@import "@fontsource-variable/host-grotesk";
@import "@fontsource-variable/newsreader";

/* Light (faithful): warm cream page #f7f1e9, near-black olive ink #20221a for type and the footer,
   cards are a 6% ink veil on the cream. Highlight is the deep teal #3d6062 and glow the butter
   #ffe7a6 (the project accent colours of the original). Chart colours are its mustard, teal,
   olive, khaki and mint. Blocks that sit on photos or the dark footer add the `dark` class to
   themselves: that gives cream type on ink below. */
:root {
  --background: oklch(0.961 0.0125 75.4);
  --foreground: oklch(0.247 0.0149 118.9);
  --card: oklch(0.937 0.0125 75.4);
  --card-foreground: oklch(0.247 0.0149 118.9);
  --popover: oklch(0.961 0.0125 75.4);
  --popover-foreground: oklch(0.247 0.0149 118.9);
  --primary: oklch(0.247 0.0149 118.9);
  --primary-foreground: oklch(0.961 0.0125 75.4);
  --secondary: oklch(0.912 0.0197 86);
  --secondary-foreground: oklch(0.247 0.0149 118.9);
  --muted: oklch(0.937 0.0125 75.4);
  --muted-foreground: oklch(0.43 0.0149 110);
  --accent: oklch(0.848 0.0307 92.4);
  --accent-foreground: oklch(0.247 0.0149 118.9);
  --destructive: oklch(0.577 0.245 27.325);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(0.247 0.0149 118.9 / 15%);
  --input: oklch(0.247 0.0149 118.9 / 25%);
  --ring: oklch(0.463 0.0404 200.4);
  --highlight: oklch(0.463 0.0404 200.4);
  --highlight-foreground: oklch(0.961 0.0125 75.4);
  --glow: oklch(0.933 0.0863 90.1);
  --chart-1: oklch(0.559 0.1142 90);
  --chart-2: oklch(0.463 0.0404 200.4);
  --chart-3: oklch(0.389 0.05 114.6);
  --chart-4: oklch(0.545 0.0513 99.6);
  --chart-5: oklch(0.936 0.0241 155.1);
  --sidebar: oklch(0.937 0.0125 75.4);
  --sidebar-foreground: oklch(0.247 0.0149 118.9);
  --sidebar-primary: oklch(0.247 0.0149 118.9);
  --sidebar-primary-foreground: oklch(0.961 0.0125 75.4);
  --sidebar-accent: oklch(0.848 0.0307 92.4);
  --sidebar-accent-foreground: oklch(0.247 0.0149 118.9);
  --sidebar-border: oklch(0.247 0.0149 118.9 / 15%);
  --sidebar-ring: oklch(0.463 0.0404 200.4);

  --typeface-body: "Host Grotesk Variable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --typeface-display: "Host Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  /* the original's accent serif (labels, roles, the second line of the award statement) */
  --typeface-serif: "Newsreader Variable", Georgia, "Times New Roman", serif;
  --radius: 0.25rem;
  --page-width: 120rem;
  --page-gutter: 1rem;
  --section-y: 5rem;
}

/* Dark (sibling): the footer's ink as the page, the cream as type. */
.dark {
  --background: oklch(0.247 0.0149 118.9);
  --foreground: oklch(0.961 0.0125 75.4);
  --card: oklch(0.3 0.0149 118.9);
  --card-foreground: oklch(0.961 0.0125 75.4);
  --popover: oklch(0.3 0.0149 118.9);
  --popover-foreground: oklch(0.961 0.0125 75.4);
  --primary: oklch(0.961 0.0125 75.4);
  --primary-foreground: oklch(0.247 0.0149 118.9);
  --secondary: oklch(0.34 0.0149 118.9);
  --secondary-foreground: oklch(0.961 0.0125 75.4);
  --muted: oklch(0.3 0.0149 118.9);
  --muted-foreground: oklch(0.961 0.0125 75.4 / 65%);
  --accent: oklch(0.389 0.05 114.6);
  --accent-foreground: oklch(0.961 0.0125 75.4);
  --destructive: oklch(0.704 0.191 22.216);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(0.961 0.0125 75.4 / 20%);
  --input: oklch(0.961 0.0125 75.4 / 25%);
  --ring: oklch(0.933 0.0863 90.1);
  --highlight: oklch(0.933 0.0863 90.1);
  --highlight-foreground: oklch(0.247 0.0149 118.9);
  --glow: oklch(0.559 0.1142 90);
  --chart-1: oklch(0.933 0.0863 90.1);
  --chart-2: oklch(0.936 0.0241 155.1);
  --chart-3: oklch(0.848 0.0307 92.4);
  --chart-4: oklch(0.545 0.0513 99.6);
  --chart-5: oklch(0.463 0.0404 200.4);
  --sidebar: oklch(0.3 0.0149 118.9);
  --sidebar-foreground: oklch(0.961 0.0125 75.4);
  --sidebar-primary: oklch(0.933 0.0863 90.1);
  --sidebar-primary-foreground: oklch(0.247 0.0149 118.9);
  --sidebar-accent: oklch(0.389 0.05 114.6);
  --sidebar-accent-foreground: oklch(0.961 0.0125 75.4);
  --sidebar-border: oklch(0.961 0.0125 75.4 / 20%);
  --sidebar-ring: oklch(0.933 0.0863 90.1);
}
